    place: place,
    content: content,
  );

  /// The journal of `date` (created if missing).
  Future<PageData> journal({required String date}) => RustLib.instance.api
      .crateApiGraphSynapseGraphJournal(that: this, date: date);

  Future<(String?, String?)> journalNeighbors({required String date}) => RustLib
      .instance
      .api
      .crateApiGraphSynapseGraphJournalNeighbors(that: this, date: date);

  /// Journals feed, newest first. With `before = None` it starts at today (creating today's
  /// journal); otherwise at the newest journal strictly before `before`.
  Future<List<PageData>> journals({String? before, required int limit}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphJournals(
        that: this,
        before: before,
        limit: limit,
      );

  /// Pages ordered by last update, most recent first.
  Future<List<PageDto>> listPages({
    required bool includeJournals,
    required int limit,
    required int offset,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphListPages(
    that: this,
    includeJournals: includeJournals,
    limit: limit,
    offset: offset,
  );

  /// Backspace at the start of `id`: its text is appended to `into` (the previous visible
  /// block) and the block is deleted. Its children keep their visual place: they take the
  /// block's slot when `into` is its parent, otherwise they become last children of `into`.
  Future<List<BlockDto>> mergeBlock({
    required String id,
    required String into,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphMergeBlock(
    that: this,
    id: id,
    into: into,
  );

  /// Moves a block with its subtree (drag and drop), possibly to another page.
  Future<List<BlockDto>> moveBlock({
    required String id,
    required String pageId,
    required Place place,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphMoveBlock(
    that: this,
    id: id,
    pageId: pageId,
    place: place,
  );

  /// Page by title or alias, created if missing (following a `[[link]]`). Date titles open
  /// the journal of that day.
  Future<PageData> openPage({required String title}) => RustLib.instance.api
      .crateApiGraphSynapseGraphOpenPage(that: this, title: title);

  /// Shift-Tab: the block moves right after its parent, adopting its following siblings as
  /// children so it keeps its visual place (Logseq's default outdenting).
  Future<List<BlockDto>> outdentBlock({required String id}) => RustLib
      .instance
      .api
      .crateApiGraphSynapseGraphOutdentBlock(that: this, id: id);

  /// Current outline of a page.
  Future<List<BlockDto>> outline({required String pageId}) => RustLib
      .instance
      .api
      .crateApiGraphSynapseGraphOutline(that: this, pageId: pageId);

  Future<PageData?> page({required String id}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphPage(that: this, id: id);

  /// Page by title or alias, without creating it.
  Future<PageData?> pageByTitle({required String title}) => RustLib.instance.api
      .crateApiGraphSynapseGraphPageByTitle(that: this, title: title);

  /// Stores in-memory bytes (clipboard, Android content URIs).
  Future<AssetDto> putAssetBytes({
    required List<int> bytes,
    String? name,
    String? mime,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphPutAssetBytes(
    that: this,
    bytes: bytes,
    name: name,
    mime: mime,
  );

  /// Copies a file into the blob store (streamed).
  Future<AssetDto> putAssetFile({required String path, String? mime}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphPutAssetFile(
        that: this,
        path: path,
        mime: mime,
      );

  /// Records navigation between pages (strengthens their synapse).
  Future<void> recordVisit({String? from, required String to}) => RustLib
      .instance
      .api
      .crateApiGraphSynapseGraphRecordVisit(that: this, from: from, to: to);

  /// Notes related to `page_id` by spreading activation.
  Future<List<RelatedDto>> related({
    required String pageId,
    required int limit,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphRelated(
    that: this,
    pageId: pageId,
    limit: limit,
  );

  Future<void> removeAlias({required String alias}) => RustLib.instance.api
      .crateApiGraphSynapseGraphRemoveAlias(that: this, alias: alias);

  Future<PageDto> renamePage({required String id, required String newTitle}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphRenamePage(
        that: this,
        id: id,
        newTitle: newTitle,
      );

  /// Blocks whose text contains `query` (for `((` autocomplete), most recent first.
  Future<List<BlockHit>> searchBlocks({
    required String query,
    required int limit,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphSearchBlocks(
    that: this,
    query: query,
    limit: limit,
  );

  /// Page titles and aliases matching `query`: exact, then prefix, then word-prefix, then
  /// substring; shorter titles first within a tier. Empty query returns recent pages.
  Future<List<TitleHit>> searchTitles({
    required String query,
    required int limit,
  }) => RustLib.instance.api.crateApiGraphSynapseGraphSearchTitles(
    that: this,
    query: query,
    limit: limit,
  );

  Future<void> setCollapsed({required String id, required bool collapsed}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphSetCollapsed(
        that: this,
        id: id,
        collapsed: collapsed,
      );

  /// Timeline data for `[from, to]` (oldest first) with titles of every page it mentions.
  Future<TimelineDto> timeline({required String from, required String to}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphTimeline(
        that: this,
        from: from,
        to: to,
      );

  /// Today's date (graph clock) as `YYYY-MM-DD`.
  String today() =>
      RustLib.instance.api.crateApiGraphSynapseGraphToday(that: this);

  /// Replaces a block's Markdown (the debounced save while typing).
  Future<void> updateBlock({required String id, required String content}) =>
      RustLib.instance.api.crateApiGraphSynapseGraphUpdateBlock(
        that: this,
        id: id,
        content: content,
      );
}
